import {createFlight,stepFlight,assistedControls,TARGET,GOAL} from './rocket-physics.js';
const $=id=>document.getElementById(id),canvas=$('flight-canvas'),ctx=canvas.getContext('2d'),keys=new Set(),held=new Set();let state=createFlight(),assist=false,last=0,acc=0,uiClock=0;
const statusNames={ready:'READY FOR FLIGHT',flying:'MISSION IN PROGRESS',paused:'FLIGHT PAUSED',landed:'LANDING CONFIRMED',crashed:'TRY ANOTHER FLIGHT'};
function release(){keys.clear();held.clear();document.querySelectorAll('[data-control]').forEach(b=>b.classList.remove('held'));}
function reset(mode=state.mode){state=createFlight(mode);release();acc=0;document.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mode===mode)));$('mission-title').textContent=mode==='launch'?'Launch. Climb. Come home.':'One burn from a better landing.';$('mission-instruction').textContent=mode==='launch'?'Reach 250 m, then return to the green landing pad.':'Take over a descending rocket and guide it to the green pad.';announce();renderUI();}
function announce(){ $('flight-status').textContent=statusNames[state.status];$('flight-message').textContent=state.reason||(state.status==='ready'?'Press Start flight when you are ready.':state.status==='paused'?'Resume when ready.':state.phase==='ascent'?'Climb through the 250 m checkpoint.':'Brake your descent and line up with the landing pad.');}
function start(){if(state.status==='ready'){state.status='flying';}else if(state.status==='flying'){state.status='paused';release();}else if(state.status==='paused'){state.status='flying';}else{reset();state.status='flying';}announce();renderUI();}
$('start-flight').onclick=start;$('reset-flight').onclick=()=>reset();document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>reset(b.dataset.mode));$('flight-assist').onchange=e=>{assist=e.target.checked;release();$('assist-note').textContent=assist?'Flight assist is piloting. Watch its burns, or switch it off to take over.':'You have control. Hold thrust to climb or brake your fall.';};
for(const b of document.querySelectorAll('[data-control]')){b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);held.add(b.dataset.control);b.classList.add('held');});for(const type of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(type,()=>{held.delete(b.dataset.control);b.classList.remove('held');});}
canvas.addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowLeft','ArrowRight','KeyA','KeyD','KeyW','KeyP','KeyR'].includes(e.code)){e.preventDefault();if(e.code==='KeyP'&&!e.repeat)start();else if(e.code==='KeyR'&&!e.repeat)reset();else keys.add(e.code);}});window.addEventListener('keyup',e=>keys.delete(e.code));canvas.addEventListener('blur',release);window.addEventListener('blur',()=>{release();if(state.status==='flying'){state.status='paused';announce();renderUI();}});document.addEventListener('visibilitychange',()=>{release();if(document.hidden&&state.status==='flying'){state.status='paused';announce();renderUI();}});
function renderUI(){ $('altitude').textContent=Math.round(state.y)+' m';$('vertical-speed').textContent=(state.vy>=0?'+':'')+state.vy.toFixed(1)+' m/s';$('horizontal-speed').textContent=state.vx.toFixed(1)+' m/s';$('fuel-value').textContent=Math.ceil(state.fuel)+'%';$('fuel-meter').value=state.fuel;$('flight-time').textContent=state.time.toFixed(1)+' s';$('checkpoint').textContent=state.reached?'COMPLETE':'250 m';$('start-flight').textContent=state.status==='flying'?'Pause':state.status==='paused'?'Resume':state.status==='ready'?'Start flight':'Fly again';$('flight-result').hidden=!['crashed','landed'].includes(state.status);$('result-title').textContent=state.status==='landed'?'Welcome back, commander.':'Every flight teaches you something.';$('result-detail').textContent=state.reason;}
const stars=Array.from({length:95},(_,i)=>({x:(i*137.37)%900,y:(i*73.1)%390,r:i%7===0?1.4:.7}));
function draw(){const w=900,h=520;ctx.clearRect(0,0,w,h);const sky=ctx.createLinearGradient(0,0,0,h);sky.addColorStop(0,'#080f1d');sky.addColorStop(1,'#182a37');ctx.fillStyle=sky;ctx.fillRect(0,0,w,h);ctx.fillStyle='#b7d4e2';for(const s of stars){ctx.globalAlpha=.25+(s.x%5)/10;ctx.beginPath();ctx.arc(s.x,s.y,s.r,0,Math.PI*2);ctx.fill();}ctx.globalAlpha=1;
ctx.strokeStyle='#a5c6d412';ctx.lineWidth=1;for(let y=50;y<470;y+=50){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(900,y);ctx.stroke();}
const ground=470,scale=1.12,checkpointY=ground-GOAL*scale;ctx.strokeStyle=state.reached?'#c4f59050':'#79bddb80';ctx.setLineDash([6,7]);ctx.beginPath();ctx.moveTo(40,checkpointY);ctx.lineTo(860,checkpointY);ctx.stroke();ctx.setLineDash([]);ctx.font='11px monospace';ctx.fillStyle='#9eb9cb';ctx.fillText(state.reached?'CHECKPOINT CLEARED':'250 m / ASCENT CHECKPOINT',40,checkpointY-12);
ctx.fillStyle='#0d1b23';ctx.beginPath();ctx.moveTo(0,450);for(let x=0;x<=900;x+=30)ctx.lineTo(x,420+Math.sin(x*.015)*15+Math.cos(x*.04)*8);ctx.lineTo(900,520);ctx.lineTo(0,520);ctx.fill();ctx.fillStyle='#142029';ctx.fillRect(0,ground,900,50);ctx.strokeStyle='#425464';ctx.beginPath();ctx.moveTo(0,ground);ctx.lineTo(900,ground);ctx.stroke();
for(const [x,color,label] of [[220,'#637687','LAUNCH'],[TARGET,'#c4f590','LAND HERE']]){ctx.fillStyle=color;ctx.fillRect(x-55,ground,110,5);ctx.font='11px monospace';ctx.textAlign='center';ctx.fillText(label,x,ground+29);ctx.fillRect(x-56,ground-8,4,8);ctx.fillRect(x+52,ground-8,4,8);}ctx.textAlign='left';
const y=ground-state.y*scale;ctx.save();ctx.translate(state.x,y);ctx.rotate(state.status==='crashed'?.45:state.steer*.1);if(state.throttle>0&&state.status==='flying'){ctx.fillStyle='#ffac61';ctx.beginPath();ctx.moveTo(-7,-9);ctx.lineTo(0,10+30*state.throttle);ctx.lineTo(7,-9);ctx.fill();ctx.fillStyle='#fff1ba';ctx.beginPath();ctx.moveTo(-4,-9);ctx.lineTo(0,5+15*state.throttle);ctx.lineTo(4,-9);ctx.fill();}ctx.fillStyle=state.status==='crashed'?'#9b7a71':'#e3ece9';ctx.beginPath();ctx.moveTo(-11,-13);ctx.lineTo(-11,-43);ctx.quadraticCurveTo(-11,-56,0,-64);ctx.quadraticCurveTo(11,-56,11,-43);ctx.lineTo(11,-13);ctx.closePath();ctx.fill();ctx.fillStyle='#58798c';ctx.fillRect(-11,-29,22,7);ctx.fillStyle='#99dbea';ctx.beginPath();ctx.arc(0,-42,5,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#b6c5ca';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-9,-18);ctx.lineTo(-22,0);ctx.moveTo(9,-18);ctx.lineTo(22,0);ctx.stroke();ctx.fillStyle='#71858c';ctx.fillRect(-7,-14,14,5);ctx.restore();
ctx.fillStyle='#c4f590';ctx.font='11px monospace';ctx.fillText('RECOVERY ZONE ±42 m',TARGET-66,ground-22);
if(state.status==='ready'||state.status==='paused'){ctx.fillStyle='#07101bc9';ctx.fillRect(280,275,340,64);ctx.fillStyle='#edf5ed';ctx.textAlign='center';ctx.font='18px sans-serif';ctx.fillText(state.status==='ready'?'Your rocket. Your flight.':'Flight paused',450,302);ctx.font='12px sans-serif';ctx.fillStyle='#a5b7c4';ctx.fillText(state.status==='ready'?'Start below · Click the scene for keyboard controls':'Select Resume to continue',450,325);ctx.textAlign='left';}}
function frame(t){const elapsed=Math.min((t-last)/1000||0,.1);last=t;acc+=elapsed;let changed=false;while(acc>=1/120){const previous=state.status,phase=state.phase;const throttle=held.has('thrust')||keys.has('Space')||keys.has('ArrowUp')||keys.has('KeyW');const steer=Number(held.has('right')||keys.has('ArrowRight')||keys.has('KeyD'))-Number(held.has('left')||keys.has('ArrowLeft')||keys.has('KeyA'));stepFlight(state,assist?assistedControls(state):{throttle:Number(throttle),steer},1/120);if(previous!==state.status||phase!==state.phase)changed=true;acc-=1/120;}if(changed){announce();release();}uiClock+=elapsed;if(uiClock>.1||changed){renderUI();uiClock=0;}draw();requestAnimationFrame(frame);}
new ResizeObserver(()=>{const dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(canvas.clientWidth*dpr);canvas.height=Math.round(canvas.clientHeight*dpr);ctx.setTransform(canvas.width/900,0,0,canvas.height/520,0,0);draw();}).observe(canvas);reset();requestAnimationFrame(frame);
